window.COZINHA_RECIPES_PARTS = window.COZINHA_RECIPES_PARTS || []; window.COZINHA_RECIPES_PARTS.push(...[{"id":"mingau-fuba-coco","title":"Mingau de fubá com coco","category":"Preparações cremosas sem lactose","image":"data:image/webp;base64,","minutes":20,"servings":2,"difficulty":"Fácil","tagline":"Creme morno e encorpado de fubá, coco e canela.","ingredients":[{"name":"fubá fino sem glúten","qty":3,"unit":"col. (sopa)"},{"name":"água","qty":1,"unit":"xíc."},{"name":"leite de coco sem açúcar","qty":1,"unit":"xíc."},{"name":"banana madura amassada","qty":0.5,"unit":"un"},{"name":"canela","qty":0.25,"unit":"col. (chá)"}],"steps":["Dissolva o fubá na água fria dentro de uma panela.","Junte o leite de coco e leve ao fogo baixo, mexendo continuamente.","Cozinhe por 12 a 15 minutos, até perder o sabor de fubá cru e engrossar.","Misture a banana amassada, cozinhe mais 2 minutos e finalize com canela."],"tip":"A banana adoça naturalmente; não é uma receita sem açúcares totais.","imageAlt":"Fotografia ilustrativa de Mingau de fubá com coco","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":585},{"id":"omelete-tomate","title":"Omelete de tomate e cebola","category":"Café da manhã","image":"data:image/webp;base64,","minutes":12,"servings":1,"difficulty":"Fácil","tagline":"Omelete dobrado com tomate fresco e cebola.","ingredients":[{"name":"ovo","qty":2,"unit":"un"},{"name":"tomate sem sementes picado","qty":0.5,"unit":"un"},{"name":"cebola picada","qty":2,"unit":"col. (sopa)"},{"name":"azeite","qty":1,"unit":"col. (chá)"},{"name":"sal","qty":1,"unit":"pitada"},{"name":"salsinha","qty":1,"unit":"col. (chá)"}],"steps":["Bata os ovos com sal e salsinha.","Aqueça o azeite e refogue a cebola por 1 minuto.","Acrescente o tomate, deixe evaporar parte da água e espalhe o recheio.","Despeje os ovos batidos, tampe e cozinhe em fogo baixo até firmar.","Dobre ao meio e sirva sem partes líquidas no centro."],"tip":"Retirar as sementes do tomate ajuda a não encharcar a omelete.","imageAlt":"Fotografia ilustrativa de Omelete de tomate e cebola","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":235},{"id":"pao-frigideira-polvilho","title":"Pão de frigideira de polvilho","category":"Pães, bolos e massas","image":"data:image/webp;base64,","minutes":20,"servings":1,"difficulty":"Fácil","tagline":"Pãozinho macio de polvilho e batata, feito na frigideira.","ingredients":[{"name":"batata cozida e bem amassada","qty":0.5,"unit":"xíc."},{"name":"polvilho doce","qty":3,"unit":"col. (sopa)"},{"name":"ovo","qty":1,"unit":"un"},{"name":"azeite","qty":1,"unit":"col. (chá)"},{"name":"fermento químico sem glúten","qty":0.25,"unit":"col. (chá)"},{"name":"sal","qty":1,"unit":"pitada"}],"steps":["Misture a batata fria, ovo, azeite e sal.","Acrescente o polvilho e o fermento até obter massa espessa e homogênea.","Aqueça frigideira antiaderente pequena e untada em fogo bem baixo.","Despeje a massa, tampe e cozinhe por 5 a 7 minutos de cada lado ou até o centro ficar totalmente firme."],"tip":"Se necessário, divida a massa em dois discos para cozinhar melhor.","imageAlt":"Fotografia ilustrativa de Pão de frigideira de polvilho","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":910},{"id":"chia-morango","title":"Pudim de chia com morangos","category":"Sobremesas sem açúcar adicionado","image":"data:image/webp;base64,","minutes":245,"servings":2,"difficulty":"Intermediária","tagline":"Creme gelado de chia e bebida vegetal com morangos.","ingredients":[{"name":"sementes de chia","qty":4,"unit":"col. (sopa)"},{"name":"bebida vegetal sem açúcar","qty":1,"unit":"xíc."},{"name":"morangos picados","qty":0.5,"unit":"xíc."},{"name":"extrato natural de baunilha sem açúcar","qty":0.5,"unit":"col. (chá)"}],"steps":["Misture chia, bebida vegetal e baunilha em um pote limpo.","Deixe descansar 10 minutos e mexa novamente para desfazer grumos.","Tampe e leve à geladeira por pelo menos 4 horas, até a chia hidratar.","Sirva com os morangos frescos."],"tip":"Mantenha refrigerado e consuma em até 24 horas se a fruta já estiver picada.","imageAlt":"Fotografia ilustrativa de Pudim de chia com morangos","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":1005},{"id":"vitamina-mamao","title":"Vitamina de mamão e banana","category":"Bebidas e extras","image":"data:image/webp;base64,","minutes":5,"servings":2,"difficulty":"Fácil","tagline":"Vitamina cremosa com fruta e bebida vegetal.","ingredients":[{"name":"mamão maduro em cubos","qty":1,"unit":"xíc."},{"name":"banana madura","qty":1,"unit":"un"},{"name":"bebida vegetal sem açúcar","qty":1,"unit":"xíc."},{"name":"cubos de gelo","qty":4,"unit":"un"}],"steps":["Higienize as frutas e corte o mamão em cubos.","Coloque mamão, banana e bebida vegetal no liquidificador.","Bata por 30 a 45 segundos até ficar homogêneo.","Acrescente gelo, bata rapidamente e sirva na hora."],"tip":"Não precisa de açúcar adicionado quando as frutas estão maduras.","imageAlt":"Imagem ilustrativa específica de vitamina de mamão e banana","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":970},{"id":"waffle-banana","title":"Waffle de banana e canela","category":"Café da manhã","image":"data:image/webp;base64,","minutes":25,"servings":2,"difficulty":"Fácil","tagline":"Waffles dourados com banana na massa e canela.","ingredients":[{"name":"banana madura amassada","qty":1,"unit":"un"},{"name":"ovo","qty":2,"unit":"un"},{"name":"farinha de arroz","qty":0.5,"unit":"xíc."},{"name":"bebida vegetal sem açúcar","qty":2,"unit":"col. (sopa)"},{"name":"fermento químico sem glúten","qty":0.5,"unit":"col. (chá)"},{"name":"canela","qty":0.25,"unit":"col. (chá)"},{"name":"azeite para untar","qty":1,"unit":"col. (chá)"}],"steps":["Aqueça a máquina de waffle conforme o fabricante.","Misture banana, ovos, farinha de arroz, bebida vegetal e canela.","Acrescente o fermento delicadamente.","Unte a máquina se necessário, coloque pequenas porções e asse até o waffle firmar e dourar."],"tip":"Evite abrir a máquina antes da massa ficar firme.","imageAlt":"Imagem ilustrativa específica de waffle de banana e canela","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":550},{"id":"bolo-cenoura","title":"Bolo de cenoura com cobertura de cacau","category":"Pães, bolos e massas","image":"data:image/webp;base64,","minutes":55,"servings":10,"difficulty":"Intermediária","tagline":"Bolo de cenoura assado com cobertura de chocolate sem leite.","ingredients":[{"name":"cenoura média picada","qty":2,"unit":"un"},{"name":"ovo","qty":3,"unit":"un"},{"name":"óleo de girassol","qty":0.3333333333333333,"unit":"xíc."},{"name":"banana bem madura","qty":2,"unit":"un"},{"name":"farinha de arroz","qty":1,"unit":"xíc."},{"name":"polvilho doce","qty":0.5,"unit":"xíc."},{"name":"fermento químico sem glúten","qty":1,"unit":"col. (sopa)"},{"name":"cacau em pó 100%","qty":3,"unit":"col. (sopa)"},{"name":"leite de coco sem açúcar","qty":0.3333333333333333,"unit":"xíc."}],"steps":["Aqueça o forno a 180 °C e unte uma forma média.","Bata cenoura, ovos, óleo e bananas até obter creme liso.","Misture a farinha de arroz e o polvilho; incorpore o creme e, por último, o fermento.","Asse por cerca de 35 a 40 minutos ou até um palito sair limpo.","Para a cobertura, aqueça cacau e leite de coco mexendo até encorpar; espalhe sobre o bolo frio."],"tip":"A doçura depende da maturação da banana. Faça teste de sabor e textura antes de comercializar esta versão.","imageAlt":"Imagem ilustrativa específica de bolo de cenoura com cobertura de cacau","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":330}]);